import { tv, type VariantProps } from "@/lib/beton/tv";

export const progress = tv({
  slots: {
    root: "flex w-full flex-col gap-2",
    header: "flex items-baseline justify-between gap-4",
    label: "font-display font-bold tracking-wide uppercase text-foreground",
    value: "font-mono font-bold text-foreground",
    track: "w-full overflow-hidden border-3 border-border bg-surface",
    indicator: [
      "h-full transition-[width] duration-100 ease-linear motion-reduce:transition-none",
      "data-indeterminate:w-2/5 data-indeterminate:animate-indeterminate",
    ],
  },
  variants: {
    variant: {
      primary: { indicator: "bg-primary" },
      secondary: { indicator: "bg-secondary" },
      success: { indicator: "bg-success" },
      danger: { indicator: "bg-danger" },
    },
    size: {
      sm: { track: "h-4", label: "text-xs", value: "text-xs" },
      md: { track: "h-6", label: "text-sm", value: "text-sm" },
      lg: { track: "h-8", label: "text-base", value: "text-base" },
    },
  },
  defaultVariants: {
    variant: "primary",
    size: "md",
  },
});

export type ProgressVariants = VariantProps<typeof progress>;

"use client";

import { Progress as BaseProgress } from "@base-ui/react/progress";
import { progress, type ProgressVariants } from "@/lib/beton/recipes/progress.recipe";
import type { ReactNode } from "react";

export interface ProgressProps
  extends Omit<BaseProgress.Root.Props, "className">, ProgressVariants {
  className?: string;
  /** Names the bar. Required unless you pass aria-label or aria-labelledby. */
  label?: ReactNode;
  /** Shows the percentage beside the label. On by default when there is a label. */
  showValue?: boolean;
}

/** How far along a task is, from zero to done. */
export function Progress({
  variant = "primary",
  size = "md",
  label,
  showValue,
  className,
  ...props
}: ProgressProps) {
  const styles = progress({ variant, size });
  const withValue = showValue ?? Boolean(label);
  return (
    <BaseProgress.Root {...props} className={styles.root({ class: className })}>
      {label || withValue ? (
        <div className={styles.header()}>
          {label ? (
            <BaseProgress.Label className={styles.label()}>{label}</BaseProgress.Label>
          ) : null}
          {withValue ? <BaseProgress.Value className={styles.value()} /> : null}
        </div>
      ) : null}
      <BaseProgress.Track className={styles.track()}>
        <BaseProgress.Indicator className={styles.indicator()} />
      </BaseProgress.Track>
    </BaseProgress.Root>
  );
}
